/** Generated from the overhaul textbook. Re-run tools/import-overhaul-courses.mjs. Do not edit by hand. */
export default {"id":"launchkey-level-16","number":16,"title":"Auxiliary DAW Integrations & Protocol Standards","skillBand":"Textbook","duration":"From the course textbook","summary":"Novation authored dedicated integration scripts for five major host DAWs (Ableton Live, Apple Logic Pro, Steinberg Cubase/Nuendo, Image-Line FL Studio, and Bitwig Studio) along with universal Mackie HUI support for other environments. This ","modules":[{"id":"launchkey-m-16-1-1","code":"16.1","title":"Auxiliary DAW Integrations & Protocol Standards","blurb":"Novation authored dedicated integration scripts for five major host DAWs (Ableton Live, Apple Logic Pro, Steinberg Cubase/Nuendo, Image-Line FL Studio, and Bitwig Studio) along with universal Mackie HUI support for other environments. This ","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-50","title":"Section overview","blocks":[{"type":"step","title":"Section 16.1 — Universal DAW Control Surface Standards","blocks":[{"type":"heading","text":"Module Overview","level":3},{"type":"prose","html":"Novation authored dedicated integration scripts for five major host DAWs (Ableton Live, Apple Logic Pro, Steinberg Cubase/Nuendo, Image-Line FL Studio, and Bitwig Studio) along with universal Mackie HUI support for other environments. This module reviews the universal baseline defaults, shared transport behaviors, and the universal continuous encoder transport map."},{"type":"heading","text":"Learning Objectives","level":3},{"type":"list","items":["Formulate the four standardized default operating modes across all supported DAWs.","Itemize universal transport and workflow button behaviors.","Contrast the Universal Transport Rotary Encoder Map with Ableton Live's dedicated transport map."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-16-1-1","title":"16.1.1: Universal Default Operating Modes","blocks":[{"type":"step","title":"16.1.1: Universal Default Operating Modes","blocks":[{"type":"prose","html":"When connecting the Launchkey MK4 61 to any officially supported DAW, the control surface script automatically initializes four standardized default modes:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                    UNIVERSAL DAW DEFAULT MODE PROFILES                        |\n+-------------------+-----------------------+-----------------------------------+\n| Hardware Plane    | Default DAW Mode      | Operational Function              |\n+-------------------+-----------------------+-----------------------------------+\n| **Encoders**      | **Plugin Mode**       | 8 parameters of focused plugin    |\n| **Pads**          | **DAW Mode**          | Clips / Mixer / Channel Rack      |\n| **Faders**        | **Volume Mode**       | Faders 1–8: Tracks; Fader 9: Mast |\n| **Fader Buttons** | **Arm / Select Mode** | Track record arming and selection |\n+-------------------+-----------------------+-----------------------------------+</pre>"}]}],"minutes":8},{"id":"launchkey-l-16-1-2","title":"16.1.2: Shared Universal Transport & Workflow Actions","blocks":[{"type":"step","title":"16.1.2: Shared Universal Transport & Workflow Actions","blocks":[{"type":"prose","html":"The following hardware actions operate identically across all supported DAWs:"},{"type":"list","items":["<strong>Play</strong>: Initiates playback (<code>Shift + Play</code> pauses).","<strong>Stop</strong>: Halts playback (second press rewinds to start).","<strong>Record</strong>: Engages main DAW recording.","<strong>Loop</strong>: Toggles timeline loop bracket.","<strong>Quantise / Undo / Metronome</strong>: Triggers native host functions."],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-16-1-3","title":"16.1.3: Universal Transport Rotary Encoder Map","blocks":[{"type":"step","title":"16.1.3: Universal Transport Rotary Encoder Map","blocks":[{"type":"prose","html":"In generic DAW environments (and DAWs other than Ableton Live), <strong>Transport Mode</strong> (<code>Shift + Pad 4</code>) adheres to the universal 8-encoder table:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                 UNIVERSAL GENERIC DAW TRANSPORT ENCODER MAP                   |\n+---------------+-----------------------+---------------------------------------+\n| Encoder #     | Control Target        | Operational Function                  |\n+---------------+-----------------------+---------------------------------------+\n| **Encoder 1** | **Scrub**             | Smooth timeline playhead scrubbing    |\n| **Encoder 2** | **Zoom**              | Horizontal timeline zoom              |\n| **Encoder 3** | **Loop Start**        | Adjusts timeline loop start marker    |\n| **Encoder 4** | **Loop End**          | Adjusts timeline loop end marker      |\n| **Encoder 5** | **Marker Select**     | Steps between arrangement markers     |\n| **Encoder 6** | *(Unassigned / Empty)*| Reserved                              |\n| **Encoder 7** | *(Unassigned / Empty)*| Reserved                              |\n| **Encoder 8** | **Tempo**             | Adjusts host master BPM               |\n+---------------+-----------------------+---------------------------------------+</pre>"},{"type":"prose","html":"<em>(Notice: Ableton Live uses a dedicated 8-encoder map with dual H/V zoom and marker selection on Encoder 6, as taught in Section 13.2).</em>"}]},{"type":"step","title":"Operational Rules Summary","blocks":[{"type":"list","items":["<strong>mustCover</strong>: 4 universal default modes; shared transport actions; universal transport encoder table; clear distinction from Live's table.","<strong>mustNotCover</strong>: Speculation regarding undocumented generic DAW scripts."],"ordered":false}]},{"type":"step","title":"Practical Guided Task & Assessment Checkpoint","blocks":[{"type":"prose","html":"<strong>Task</strong>: Recite the 4 default DAW modes from memory, and contrast Encoder 2's role in the Universal Transport map (Timeline Zoom) versus Ableton Live's Transport map (View-Dependent Horizontal Zoom/Scroll)."},{"type":"prose","html":"<strong>Checkpoint Validation</strong>:"},{"type":"list","items":["4 default modes stated accurately: Encoders (Plugin), Pads (DAW), Faders (Volume), Fader Buttons (Arm/Select).","Difference between universal and Live transport maps clearly formulated."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"launchkey-m-16-2-2","code":"16.2","title":"Auxiliary DAW Integrations & Protocol Standards","blurb":"Novation authored a deep, native integration script for Apple Logic Pro (macOS only). This module details Logic Pro's Smart Controls mapping, the dedicated 8-encoder Channel EQ page, dual-page Mixer pads, and bidirectional Live Loops cell a","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-51","title":"Section overview","blocks":[{"type":"step","title":"Section 16.2 — Apple Logic Pro Integration (macOS)","blocks":[{"type":"heading","text":"Module Overview","level":3},{"type":"prose","html":"Novation authored a deep, native integration script for Apple Logic Pro (macOS only). This module details Logic Pro's Smart Controls mapping, the dedicated 8-encoder Channel EQ page, dual-page Mixer pads, and bidirectional <strong>Live Loops</strong> cell and scene triggering."},{"type":"prose","html":"<em>(Workstation Note: Logic Pro operates exclusively on Apple macOS. Windows-based students should study this module for structural reference).</em>"},{"type":"heading","text":"Learning Objectives","level":3},{"type":"list","items":["Command Logic Pro's <strong>Smart Controls</strong> via Plugin Mode and navigate multi-page Smart Controls.","Formulate the encoder layout of Logic's dedicated <strong>Channel EQ page</strong>.","Navigate the dual-page <strong>Mixer Pads</strong> (Page 1: Select/Arm vs. Page 2: Solo/Mute).","Trigger non-linear grid cells and column scenes in <strong>Live Loops Mode</strong>.","Navigate Live Loops tracks and scenes using hardware banking controls."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-16-2-1","title":"16.2.1: Plugin Mode & Smart Controls Mapping","blocks":[{"type":"step","title":"16.2.1: Plugin Mode & Smart Controls Mapping","blocks":[{"type":"prose","html":"In Logic Pro, setting Encoder Mode to <strong>Plugin</strong> (<code>Shift + Pad 1</code>):"},{"type":"list","items":["<strong>Smart Controls Integration</strong>: Encoders 1–8 automatically map to Logic's focused track <strong>Smart Controls</strong> (press computer key <code>B</code> to open the Smart Controls pane in Logic).","<strong>Page Navigation</strong>: If a patch contains more than 8 Smart Controls, <code>Encoder Bank Up / Down</code> navigates across subsequent parameter pages."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-16-2-2","title":"16.2.2: The 8-Encoder Mixer EQ Page","blocks":[{"type":"step","title":"16.2.2: The 8-Encoder Mixer EQ Page","blocks":[{"type":"prose","html":"In Logic Mixer Mode (<code>Shift + Pad 2</code>), pressing <code>Encoder Bank Up</code> twice accesses the <strong>Channel EQ Page</strong>:"},{"type":"list","items":["<strong>Automatic Instantiation</strong>: If the focused track lacks an EQ, turning an encoder automatically inserts a native Logic Channel EQ.","<strong>Frequency/Gain Pairs</strong>: Odd encoders control Frequency; even encoders control Gain:","Enc 1 / 2: Low Cut / Low Shelf (Freq / Gain)","Enc 3 / 4: Low-Mid Bell (Freq / Gain)","Enc 5 / 6: High-Mid Bell (Freq / Gain)","Enc 7 / 8: High Shelf / High Cut (Freq / Gain)"],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-16-2-3","title":"16.2.3: Dual-Page Mixer Pads","blocks":[{"type":"step","title":"16.2.3: Dual-Page Mixer Pads","blocks":[{"type":"prose","html":"In Logic DAW Pad Mode (<code>Shift + Pad 9</code>):"},{"type":"list","items":["<strong>Page 1 (Select &amp; Arm)</strong>: Top row selects tracks; bottom row toggles Track Arm.","<strong>Page 2 (Solo &amp; Mute)</strong>: Top row toggles Solo; bottom row toggles Mute.","Press <code>Pad Bank Up / Down</code> to alternate between Page 1 and Page 2."],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-16-2-4","title":"16.2.4: Live Loops Grid & Scene Triggering","blocks":[{"type":"step","title":"16.2.4: Live Loops Grid & Scene Triggering","blocks":[{"type":"prose","html":"Pressing <code>Function</code> while in DAW Pad Mode toggles between Mixer Pads and <strong>Live Loops Mode</strong>:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                    LOGIC PRO LIVE LOOPS PAD TOPOLOGY                          |\n+-------------------------------------------------------------------------------+\n| **Top Row (Pads 1–8)**: Loops for the Currently Selected Track                |\n| - Triggers individual non-linear loop cells for the focused instrument.       |\n+-------------------------------------------------------------------------------+\n| **Bottom Row (Pads 9–16)**: Scene Triggers (Columns)                          |\n| - Triggers entire vertical scene columns across the full Logic arrangement.   |\n+-------------------------------------------------------------------------------+</pre>"},{"type":"list","items":["<strong>Navigation</strong>: <code>Pad Bank Up / Down</code> scrolls through tracks; <code>Track &lt; &gt;</code> scrolls horizontally through scenes/columns.","<strong>Timing</strong>: Cell launching adheres to Logic’s project <strong>Quantize Start</strong> setting."],"ordered":true}]},{"type":"step","title":"Operational Rules Summary","blocks":[{"type":"list","items":["<strong>mustCover</strong>: Logic Smart Controls; Channel EQ frequency/gain pairs; Mixer dual-page pads; Live Loops row/column mapping (Top = selected track loops, Bottom = scenes); macOS exclusivity.","<strong>mustNotCover</strong>: Speculation regarding Logic on Windows."],"ordered":false}]},{"type":"step","title":"Practical Guided Task & Assessment Checkpoint","blocks":[{"type":"prose","html":"<strong>Task (macOS workstations with Logic Pro)</strong>: Open Logic Pro, focus an audio track, enter Plugin Mode to verify Smart Controls, switch to Channel EQ page, and toggle <code>Function</code> to trigger a Live Loops scene. <em>(Windows students record a theoretical validation note).</em>"},{"type":"prose","html":"<strong>Checkpoint Validation</strong>:"},{"type":"list","items":["Smart Controls follow hardware encoders.","Live Loops pad matrix triggers individual loops and full vertical scenes."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"launchkey-m-16-3-3","code":"16.3","title":"Auxiliary DAW Integrations & Protocol Standards","blurb":"Novation authored a native MIDI Remote integration script for Steinberg Cubase (Cubase 12 / 13 / 14) and Nuendo. This module details the Cubase/Nuendo default profile, 8 Quick Controls integration, 4-band Channel EQ mapping, and dual-page m","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-52","title":"Section overview","blocks":[{"type":"step","title":"Section 16.3 — Steinberg Cubase & Nuendo Integration","blocks":[{"type":"heading","text":"Module Overview","level":3},{"type":"prose","html":"Novation authored a native MIDI Remote integration script for Steinberg <strong>Cubase</strong> (Cubase 12 / 13 / 14) and <strong>Nuendo</strong>. This module details the Cubase/Nuendo default profile, 8 Quick Controls integration, 4-band Channel EQ mapping, and dual-page mixer pad control."},{"type":"heading","text":"Learning Objectives","level":3},{"type":"list","items":["Formulate the operational parity between Steinberg Cubase and Nuendo under the Launchkey MK4 script.","Command Cubase <strong>Quick Controls</strong> via Plugin Mode.","Formulate the encoder mapping for Cubase's 4-band <strong>Channel EQ page</strong>.","Navigate the dual-page <strong>Mixer Pads</strong> (Select/Arm vs. Solo/Mute)."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-16-3-1","title":"16.3.1: Cubase & Nuendo Parity and Defaults","blocks":[{"type":"step","title":"16.3.1: Cubase & Nuendo Parity and Defaults","blocks":[{"type":"list","items":["<strong>Nuendo Parity</strong>: Steinberg Nuendo shares the identical audio/MIDI engine as Cubase; the Launchkey MK4 control surface script behaves with complete feature parity across both hosts.","<strong>Default Startup Profile</strong>:","Encoders: <strong>Plugin Mode</strong>","Pads: <strong>DAW Mode</strong>","Faders: <strong>Volume Mode</strong> (Faders 1–8 Track Volume, Fader 9 Master)","MIDI Remote Panel in Cubase displays dynamic visual feedback mirroring the physical surface."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-16-3-2","title":"16.3.2: Plugin Mode & 8 Quick Controls","blocks":[{"type":"step","title":"16.3.2: Plugin Mode & 8 Quick Controls","blocks":[{"type":"prose","html":"In Cubase Plugin Mode (<code>Shift + Pad 1</code>):"},{"type":"list","items":["Encoders 1–8 automatically bind to the focused track’s <strong>8 Quick Controls</strong> (or focused VST plugin parameters).","The Launchkey OLED display dynamically updates with the parameter names and values assigned in Cubase's Quick Controls rack."],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-16-3-3","title":"16.3.3: The 4-Band Channel EQ Page","blocks":[{"type":"step","title":"16.3.3: The 4-Band Channel EQ Page","blocks":[{"type":"prose","html":"In Mixer Mode (<code>Shift + Pad 2</code>), pressing <code>Encoder Bank Up</code> accesses the native Cubase <strong>Channel EQ Page</strong>:"},{"type":"list","items":["Maps 4 parametric EQ bands across 8 encoders in Frequency/Gain pairs:","Enc 1 / 2: <strong>Low Band</strong> (Frequency / Gain)","Enc 3 / 4: <strong>Low-Mid (LMF) Band</strong> (Frequency / Gain)","Enc 5 / 6: <strong>High-Mid (HMF) Band</strong> (Frequency / Gain)","Enc 7 / 8: <strong>High Band</strong> (Frequency / Gain)"],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-16-3-4","title":"16.3.4: Dual-Page Mixer Pads","blocks":[{"type":"step","title":"16.3.4: Dual-Page Mixer Pads","blocks":[{"type":"prose","html":"In DAW Pad Mode (<code>Shift + Pad 9</code>):"},{"type":"list","items":["<strong>Page 1 (Select &amp; Arm)</strong>:","Top Row (Pads 1–8): Selects Tracks 1–8.","Bottom Row (Pads 9–16): Toggles Record Arm for Tracks 1–8.","<strong>Page 2 (Solo &amp; Mute)</strong>:","Top Row (Pads 1–8): Toggles <strong>Solo</strong> (Illuminates <strong>Pink</strong> when soloed).","Bottom Row (Pads 9–16): Toggles <strong>Mute</strong> (Illuminates <strong>Yellow</strong> when muted).","Press <code>Pad Bank Up / Down</code> to toggle between Page 1 and Page 2."],"ordered":false}]},{"type":"step","title":"Operational Rules Summary","blocks":[{"type":"list","items":["<strong>mustCover</strong>: Cubase/Nuendo parity; 8 Quick Controls in Plugin mode; 4-band Channel EQ frequency/gain pairs; dual-page mixer pads with Pink Solo and Yellow Mute.","<strong>mustNotCover</strong>: Inventing non-existent Cubase clip launching features (Cubase does not have a native non-linear clip matrix supported by this script)."],"ordered":false}]},{"type":"step","title":"Practical Guided Task & Assessment Checkpoint","blocks":[{"type":"prose","html":"<strong>Task (for workstations with Cubase/Nuendo)</strong>: Open Cubase, assign 8 Quick Controls to a synth track, engage Plugin Mode, and verify parameter tracking on the OLED screen. Switch to Mixer Page 2 and test Pink Solo and Yellow Mute pads. <em>(If uninstalled, record a standard gap note).</em>"},{"type":"prose","html":"<strong>Checkpoint Validation</strong>:"},{"type":"list","items":["Quick Controls follow hardware encoders.","Solo/Mute pads reflect official Pink/Yellow color states."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"launchkey-m-16-4-4","code":"16.4","title":"Auxiliary DAW Integrations & Protocol Standards","blurb":"Novation authored comprehensive native control scripts for Image-Line FL Studio and Bitwig Studio. This module covers FL Studio's 5-page mixer architecture and Channel Rack pad triggering, alongside Bitwig Studio’s Remote Controls, non-line","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-53","title":"Section overview","blocks":[{"type":"step","title":"Section 16.4 — Image-Line FL Studio & Bitwig Studio Integration","blocks":[{"type":"heading","text":"Module Overview","level":3},{"type":"prose","html":"Novation authored comprehensive native control scripts for Image-Line <strong>FL Studio</strong> and <strong>Bitwig Studio</strong>. This module covers FL Studio's 5-page mixer architecture and Channel Rack pad triggering, alongside Bitwig Studio’s Remote Controls, non-linear Clip Launcher, advanced Step Sequencer with micro-editing (Chance, Repeat, Timbre), and 4-semitone Drum Machine banking."},{"type":"heading","text":"Learning Objectives","level":3},{"type":"list","items":["Formulate the 5-page mixer architecture and 3-band Channel EQ mapping in FL Studio.","Trigger FL Studio Channel Rack instruments using the 16-pad array at root pitch C5.","Configure Bitwig Studio recording targets and cycle Remote Control layers (Device, Track, Project).","Command the Bitwig Step Sequencer, including micro-editing of <strong>Chance</strong>, <strong>Repeat</strong>, <strong>Timbre</strong>, and <strong>Aftertouch</strong>.","Execute 4-semitone Drum Machine banking in Bitwig Studio."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-16-4-1","title":"16.4.1: Image-Line FL Studio Architecture","blocks":[{"type":"step","title":"16.4.1: Image-Line FL Studio Architecture","blocks":[{"type":"list","items":["<strong>Plugin Mode (<code>Shift + Pad 1</code>)</strong>:","Encoders 1–8 map to 8 primary parameters of focused native FL Studio instruments (e.g., FLEX, Sytrus, 3x OSC).","Third-party VSTs follow user-defined Custom Modes.","<strong>The 5-Page Mixer Architecture</strong>:","In Mixer Mode (<code>Shift + Pad 2</code>), pressing <code>Encoder Bank Up / Down</code> cycles across <strong>5 distinct mixer planes</strong>:","<em>Page 1</em>: <strong>Channel Rack Volume</strong>","<em>Page 2</em>: <strong>Channel Rack Pan</strong>","<em>Page 3</em>: <strong>Mixer Insert Volume</strong>","<em>Page 4</em>: <strong>Mixer Insert Pan</strong>","<em>Page 5</em>: <strong>Channel EQ</strong> (Encoders 1–6 control Low Shelf, Peaking Mid, and High Shelf Frequency &amp; Gain).","<strong>DAW Pad Mode (Channel Rack Triggering)</strong>:","In DAW Pad Mode (<code>Shift + Pad 9</code>), the 16 pads map directly to 16 instruments in the FL Studio Channel Rack.","Striking a pad triggers that channel’s instrument at standard root note <strong>C5 (MIDI Note 60)</strong>.","<strong>Fader 9</strong> operates as the dedicated FL Master Volume fader."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-16-4-2","title":"16.4.2: Bitwig Studio Deep Integration","blocks":[{"type":"step","title":"16.4.2: Bitwig Studio Deep Integration","blocks":[{"type":"list","items":["<strong>Remote Controls Paging</strong>:","In Bitwig Plugin Mode (<code>Shift + Pad 1</code>), holding <code>Shift</code> and pressing <code>Pad 1</code> repeatedly cycles the 8 encoders through:","<strong>Device Remote Controls</strong> (Focused VST/device macro parameters)","<strong>Track Remote Controls</strong> (Track-level macros)","<strong>Project Remote Controls</strong> (Global project macros)","<strong>Bitwig Clip Launcher Mode (<code>Shift + Pad 9</code> once)</strong>:","16 pads mirror Bitwig's non-linear Clip Launcher with track color tracking.","Pressing <code>Capture MIDI</code> functions as the <strong>ALT-trigger</strong> modifier in Bitwig.","<code>Function</code> cycles pad rows through Clip Launch (White), Track Stop (Red), Solo (Yellow), and Mute (Orange)."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-16-4-3","title":"16.4.3: Bitwig Advanced Step Sequencer","blocks":[{"type":"step","title":"16.4.3: Bitwig Advanced Step Sequencer","blocks":[{"type":"prose","html":"When step sequencing inside Bitwig Studio, holding any step pad and rotating Encoders 1–8 unlocks Bitwig's unique advanced micro-editing parameters:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                 BITWIG SEQUENCER STEP EDIT ENCODER MATRIX                     |\n+---------------+-----------------------+---------------------------------------+\n| Encoder #     | Bitwig Step Parameter | Operational Function                  |\n+---------------+-----------------------+---------------------------------------+\n| **Encoder 1** | **Velocity**          | Step strike velocity (1–127)          |\n| **Encoder 2** | **Length (Coarse)**   | Full-step duration                    |\n| **Encoder 3** | **Length (Fine)**     | Sub-step fractional duration          |\n| **Encoder 4** | **Chance**            | Probability of step firing (0–100%)   |\n| **Encoder 5** | **Repeat**            | Burst ratcheting (1 to 8 triggers)    |\n| **Encoder 6** | **Repeat Curve**      | Accelerating / decelerating bursts    |\n| **Encoder 7** | **Timbre**            | Per-note MPE timbre parameter         |\n| **Encoder 8** | **Aftertouch**        | Per-note initial pressure value       |\n+---------------+-----------------------+---------------------------------------+</pre>"},{"type":"list","items":["<strong>Shortcuts</strong>: <code>Function + Pad Bank Up</code> duplicates the clip; <code>Function + Pad Bank Down</code> alters the sequence grid resolution."],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-16-4-4","title":"16.4.4: Bitwig Drum Machine 4-Semitone Banking","blocks":[{"type":"step","title":"16.4.4: Bitwig Drum Machine 4-Semitone Banking","blocks":[{"type":"prose","html":"When Drum Mode is active targeting a Bitwig Drum Machine:"},{"type":"list","items":["Pads map starting at <code>C1 (Channel 10)</code>.","<strong>4-Semitone Banking</strong>: Pressing <code>Pad Bank Up / Down</code> shifts the pad window by <strong>4 semitones</strong> (matching Bitwig's 4×4 drum cell layout), rather than full octaves."],"ordered":false}]},{"type":"step","title":"Operational Rules Summary","blocks":[{"type":"list","items":["<strong>mustCover</strong>: FL 5 mixer pages; FL 3-band EQ; FL Channel Rack C5 pad triggering; Bitwig Remote Controls cycling; Bitwig ALT-trigger; Bitwig 8-parameter Step Sequencer (including Chance, Repeat, Timbre); Bitwig 4-semitone drum banking.","<strong>mustNotCover</strong>: Requiring FL Studio or Bitwig for studio graduation (Live 12 remains the primary studio DAW)."],"ordered":false}]},{"type":"step","title":"Practical Guided Task & Assessment Checkpoint","blocks":[{"type":"prose","html":"<strong>Task (Optional)</strong>: If FL Studio or Bitwig Studio is installed, connect the Launchkey and verify native script detection and pad color mirroring. <em>(If neither is installed, record a standard gap note).</em>"},{"type":"prose","html":"<strong>Checkpoint Validation</strong>:"},{"type":"list","items":["Script communicates natively without manual MIDI mapping.","All documented encoder pages and pad colors verified against official specifications."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"launchkey-m-16-5-5","code":"16.5","title":"Auxiliary DAW Integrations & Protocol Standards","blurb":"For digital audio workstations that do not possess a dedicated native Python control surface script (e.g., Avid Pro Tools, Cockos Reaper, PreSonus Studio One), the Launchkey MK4 61 provides compatibility via the industry-standard Mackie HUI","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-54","title":"Section overview","blocks":[{"type":"step","title":"Section 16.5 — Mackie HUI Host Protocol Implementations","blocks":[{"type":"heading","text":"Module Overview","level":3},{"type":"prose","html":"For digital audio workstations that do not possess a dedicated native Python control surface script (e.g., Avid Pro Tools, Cockos Reaper, PreSonus Studio One), the Launchkey MK4 61 provides compatibility via the industry-standard <strong>Mackie HUI (Human User Interface)</strong> protocol. This module covers HUI protocol architecture, host-specific peripheral setup, standard mapping boundaries, and documented knowledge gaps (Reason and Ardour)."},{"type":"heading","text":"Learning Objectives","level":3},{"type":"list","items":["Formulate the technical distinction between native bidirectional scripts and the legacy Mackie HUI emulation layer.","Configure HUI peripherals in <strong>Avid Pro Tools</strong>, <strong>Cockos Reaper</strong>, and <strong>PreSonus Studio One</strong>.","Identify standard HUI mapped functions (Mute, Solo, Pan, Sends A–E, Transport, Faders 1–8).","Document official curriculum knowledge gaps regarding Propellerhead Reason and Ardour."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-16-5-1","title":"16.5.1: Mackie HUI Protocol Scope vs. Native Scripts","blocks":[{"type":"step","title":"16.5.1: Mackie HUI Protocol Scope vs. Native Scripts","blocks":[{"type":"list","items":["<strong>HUI Architecture</strong>: A legacy 7-bit MIDI-encoded control protocol originally developed by Mackie and Digidesign. It provides basic mixer, fader, pan, mute, solo, and transport handshakes.","<strong>Functional Boundaries</strong>: HUI <strong>does not support</strong> modern non-linear clip launching, step sequencing, native plugin parameter auto-population, or bidirectional Global Scale synchronization."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-16-5-2","title":"16.5.2: Host-Specific HUI Peripheral Setup","blocks":[{"type":"step","title":"16.5.2: Host-Specific HUI Peripheral Setup","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                    HUI PERIPHERAL CONFIGURATION MATRIX                        |\n+-------------------+---------------------------+-------------------------------+\n| Host DAW          | Configuration Menu Path   | Required Port Assignments     |\n+-------------------+---------------------------+-------------------------------+\n| **Avid**          | `Setup &gt; Peripherals &gt;`   | Type: **HUI** (8 Channels)    |\n| **Pro Tools**     | `MIDI Controllers` tab    | Win: `MIDIIN2` / `MIDIOUT2`   |\n|                   |                           | Mac: `DAW Out` / `DAW In`     |\n+-------------------+---------------------------+-------------------------------+\n| **Cockos**        | `Preferences &gt; Control/`  | Add device: **HUI (partial)** |\n| **Reaper**        | `OSC/web`                 | Win: `MIDIIN2` / `MIDIOUT2`   |\n|                   |                           | Mac: `DAW Out` / `DAW In`     |\n+-------------------+---------------------------+-------------------------------+\n| **PreSonus**      | `Options &gt; External`      | Device 1: \"New Keyboard\" (MIDI)|\n| **Studio One**    | `Devices`                 | Device 2: \"Mackie HUI\" (DAW)  |\n+-------------------+---------------------------+-------------------------------+</pre>"}]}],"minutes":8},{"id":"launchkey-l-16-5-3","title":"16.5.3: Standard HUI Control Surface Mapping","blocks":[{"type":"step","title":"16.5.3: Standard HUI Control Surface Mapping","blocks":[{"type":"prose","html":"When operating under HUI emulation:"},{"type":"list","items":["<strong>Faders 1–8</strong>: Control 8 track volume faders. (Fader 9 operates as Master in supported hosts).","<strong>Fader Buttons 1–8</strong>: Control Track Select or Record Arm.","<strong>Encoders 1–8</strong>: Control Track Pan (Mixer Mode) and Sends A through E (via Banking).","<strong>Pads</strong>: Function as Track Mute and Track Solo buttons.","<strong>Transport</strong>: Play, Stop, Record, and Loop operate standardly."],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-16-5-4","title":"16.5.4: Documented Knowledge Gaps (Reason & Ardour)","blocks":[{"type":"step","title":"16.5.4: Documented Knowledge Gaps (Reason & Ardour)","blocks":[{"type":"prose","html":"Novation's product comparison lists Reason and Ardour among compatible DAWs. However, the official Launchkey 61 User Guide contains <strong>no published procedural chapters or mapping tables for Reason or Ardour</strong>."},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------+\n|                  DOCUMENTED CURRICULUM GAP: REASON &amp; ARDOUR             |\n|                                                                         |\n|  Status: {type: 'gap'}                                                  |\n|  Grounding Rule Enforcement:                                            |\n|  Because Novation did not publish dedicated step-by-step procedures     |\n|  for Reason or Ardour in the official Launchkey 61 DAW User Guide,      |\n|  this curriculum will NOT invent speculative setup steps.               |\n|  Users in these hosts should utilize generic Mackie HUI or custom MIDI  |\n|  learn on Interface 1 (MIDI port).                                      |\n+-------------------------------------------------------------------------+</pre>"}]},{"type":"step","title":"Operational Rules Summary","blocks":[{"type":"list","items":["<strong>mustCover</strong>: HUI definition (HUI ≠ full script); Pro Tools, Reaper, and Studio One port binding; HUI standard mapped parameters; explicit documentation of Reason/Ardour knowledge gaps.","<strong>mustNotCover</strong>: Inventing fake Reason or Ardour setup walkthroughs."],"ordered":false}]},{"type":"step","title":"Practical Guided Task & Assessment Checkpoint","blocks":[{"type":"prose","html":"<strong>Task</strong>: In a single concise sentence, define the technical definition and operational limitations of the Mackie HUI protocol when compared to native control surface scripts."},{"type":"prose","html":"<strong>Checkpoint Validation</strong>:"},{"type":"list","items":["Statement confirms HUI is a legacy protocol providing basic mixer, fader, pan, and transport control.","Statement confirms HUI lacks native clip launching, step sequencing, and bidirectional scale sync."],"ordered":false}]}],"minutes":8}],"exercises":[]}]};
